				lastUpdated =
					response.data.updates[response.data.updates.length - 1].updated

				self.postMessage({
					type: 'update',
					status: 'running',
					mode: updateType,
					interval,
					message: '[Worker] 200 got updates',
					updates: response.data.updates,
					lastUpdate: lastUpdated,
				})
