    while (true) {
      await run()
      sendMessage({ type: 'status', status: 'idle', mode: updateType, interval })
      await sleep(interval)
    }
  }

  if (updateType === 'longInquirying') {
    sendMessage({
      type: 'info',
      status: 'starting',
      mode: updateType,
      interval,
      message: '[Worker] Started long inquirying.',
    })
