				type: 'status',
				status: 'idle',
				mode: updateType,
				interval,
			})
			await sleep(interval)
		}
	}

	if (updateType === 'longInquirying') {
		self.postMessage({
			type: 'info',
			status: 'starting',
			mode: updateType,
			interval,
			message: '[Worker] Started long inquirying.',
		})
		while (true) {
			await run()
		}
	}
